recipes.code:
{
  "inputs": [
    {
      "id": "policyforge-api-key",
      "type": "promptString",
      "description": "PolicyForge API key — create one at https://policyforge.co/api-dashboard",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@policyforge/mcp@0.4.0"
      ],
      "env": {
        "POLICYFORGE_API_KEY": "${input:policyforge-api-key}"
      }
    }
  }
}
